import React, { useEffect, useState } from "react";

function SavedPage({ token }) {
  const [saved, setSaved] = useState([]);

  useEffect(() => {
    if (!token) return;
    fetch("http://127.0.0.1:8000/api/saved/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then(setSaved)
      .catch(console.error);
  }, [token]);

  if (!token) return <p>Увійдіть, щоб переглянути збережене.</p>;

  if (saved.length === 0) return <p>Немає збережених статей.</p>;

  return (
    <div className="saved-container">
      <h2>📚 Збережені статті</h2>
      {saved.map((s) => (
        <div key={s.id} className="saved-article">
          {/* Заголовок */}
          <h3>{s.title}</h3>

          {/* Основний текст */}
          <p>{s.content}</p>

          {/* Фото, якщо є */}
          {s.image && <img src={s.image} alt={s.title} style={{ maxWidth: "100%" }} />}

          {/* Відео, якщо є */}
          {s.video && (
            <video controls style={{ maxWidth: "100%" }}>
              <source src={s.video} type="video/mp4" />
              Ваш браузер не підтримує відтворення відео.
            </video>
          )}

          {/* Коментарі, якщо є */}
          {s.comments && s.comments.length > 0 && (
            <div className="comments">
              <h4>Коментарі:</h4>
              <ul>
                {s.comments.map((c) => (
                  <li key={c.id}>
                    <b>{c.author}:</b> {c.text}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

export default SavedPage;
